import React, { useState } from 'react';

function PalindromeChecker() {
  const [text, setText] = useState('');
  const [result, setResult] = useState('');

  const handleChange = (e) => {
    const input = e.target.value;
    setText(input);

    // Remove non-alphanumeric characters and make lowercase
    const clean = input.toLowerCase().replace(/[^a-z0-9]/gi, '');
    const reverse = clean.split('').reverse().join('');

    if (clean && clean === reverse) {
      setResult('Palindrome');
    } else {
      setResult('Not a Palindrome');
    }
  };

  return (
    <div className="container d-flex justify-content-center align-items-center vh-100">
      <div className="text-center w-100" style={{ maxWidth: '400px' }}>
        <h3>Palindrome Checker</h3>
        <input
          type="text"
          className="form-control text-center mt-3"
          value={text}
          onChange={handleChange}
          placeholder="Type here..."
        />
        {text && (
          <p
            className={`mt-3 fw-bold ${
              result === 'Palindrome' ? 'text-success' : 'text-danger'
            }`}
          >
            {result}
          </p>
        )}
      </div>
    </div>
  );
}

export default PalindromeChecker;
